            ["World {index} (not released)"] = "Welt {index} (unveröffentlicht)",
            ["Enable an activity to begin."] = "Aktiviere eine Aktivität, um zu beginnen.",
            ["Preferences are saved on this device. Activities start disabled."] = "Einstellungen werden auf diesem Gerät gespeichert. Aktivitäten sind beim Start ausgeschaltet.",
            ["File saving is unavailable. Preferences stay in this session."] = "Dateispeicherung ist nicht verfügbar. Einstellungen bleiben nur in dieser Sitzung erhalten.",
            ["All buys the cheapest eligible upgrade. Select one to focus it."] = "„Alle“ kauft die günstigste geeignete Verbesserung. Wähle eine aus, um dich darauf zu konzentrieren.",
            ["Auto Equip Finds"] = "Funde automatisch ausrüsten",
            ["Auto Skip Star Reveal"] = "Sternanimation automatisch überspringen",
            ["Auto Stars"] = "Sterne automatisch erzeugen",
            ["Buy eligible upgrades with Stardust, preserving your reserve and session budget."] = "Kauft geeignete Verbesserungen mit Sternenstaub und hält Reserve sowie Sitzungsbudget ein.",
            ["Buy upgrades with existing Stardust and confirm each purchase before the next."] = "Kauft Verbesserungen mit vorhandenem Sternenstaub und bestätigt jeden Kauf vor dem nächsten.",
            ["Choose growth, nearby objects or undiscovered Index entries."] = "Wähle Wachstum, nahe Objekte oder noch unentdeckte Indexeinträge.",
            ["Choose how to reach objects. Size checks and pickup confirmation stay with the game."] = "Wähle, wie du Objekte erreichst. Größenprüfung und Sammelbestätigung übernimmt das Spiel.",
            ["Claim rewards for discovered Index entries."] = "Holt Belohnungen für entdeckte Indexeinträge ab.",
            ["Collect objects that fit your confirmed ball size. Native pickup controls confirm collection."] = "Sammelt Objekte passend zur bestätigten Größe deiner Kugel. Das Sammelsystem des Spiels bestätigt den Erfolg.",
            ["Daily and playtime claims wait for eligibility and share a confirmation queue."] = "Tägliche und Spielzeitbelohnungen warten auf erfüllte Bedingungen und nutzen dieselbe Bestätigungswarteschlange.",
            ["Enable Auto Claim Rewards to begin."] = "Aktiviere zum Start das automatische Abholen von Belohnungen.",
            ["Enable Auto Farm to begin."] = "Aktiviere zum Start das automatische Farmen.",
            ["Enable Auto Skip Star Reveal to return to your active farm after earning Stars."] = "Aktiviere das automatische Überspringen der Sternanimation, um nach erhaltenen Sternen zum laufenden Farmen zurückzukehren.",
            ["Enable Auto Upgrades when ready."] = "Aktiviere die automatischen Verbesserungen, sobald du bereit bist.",
            ["Equip the best owned Finds and claim discovered Index rewards."] = "Rüstet deine besten Funde aus und holt Belohnungen entdeckter Indexeinträge ab.",
            ["Equip your best owned Finds using the game's own selection rules."] = "Rüstet deine besten Funde nach den Auswahlregeln des Spiels aus.",
            ["Farm, make Stars, improve your loadout and collect rewards in one session."] = "Farme, erzeuge Sterne, verbessere deine Ausrüstung und hole Belohnungen in einer Sitzung ab.",
            ["Finds and Index"] = "Funde und Index",
            ["Finds off"] = "Funde aus",
            ["Index off"] = "Index aus",
            ["Keep Stardust"] = "Sternenstaubreserve",
            ["Make a Star when the game confirms its size requirement. Stars reset run size."] = "Erzeugt einen Stern, sobald das Spiel die benötigte Größe bestätigt. Sterne setzen die Größe des Durchlaufs zurück.",
            ["Maximum nearby search area in studs. Streaming limits which objects are available."] = "Maximaler Suchbereich in Studs. Nur vom Spiel geladene Objekte sind verfügbar.",
            ["Maximum Stardust to spend on upgrades this session. Zero means unlimited."] = "Maximaler Sternenstaub für Verbesserungen in dieser Sitzung. Null = unbegrenzt.",
            ["Minimum Stardust to retain after an upgrade purchase."] = "Sternenstaub, der nach einem Verbesserungskauf mindestens übrig bleiben muss.",
            ["Only discovered, unclaimed entries are collected."] = "Holt nur noch nicht abgeholte Belohnungen entdeckter Einträge ab.",
            ["Resume Auto Farm when a new local ball becomes available."] = "Setzt das automatische Farmen fort, sobald deine neue Kugel verfügbar ist.",
            ["Search radius"] = "Suchradius",
            ["Size"] = "Größe",
            ["Skip the reveal and return to play after a confirmed Star. Your enabled Auto Farm resumes through normal game controls."] = "Überspringt die Animation und kehrt nach einem bestätigten Stern ins Spiel zurück. Aktiviertes automatisches Farmen läuft über die reguläre Spielsteuerung weiter.",
            ["Star reveal skip off"] = "Überspringen der Sternanimation aus",
            ["Stardust"] = "Sternenstaub",
            ["Stars off"] = "Sternerzeugung aus",
