            ["Index"] = "Index",
            ["All"] = "Alle",
            ["1 to 10 objects between sets. Training resumes after stamina recovers."] = "1 bis 10 Objekte zwischen den Sätzen. Das Training geht nach der Ausdauererholung weiter.",
            ["1 to 50 copies. Existing Backpack and equipped tool counts are included."] = "1 bis 50 Stück. Vorhandene Exemplare im Rucksack und ausgerüstete Werkzeuge zählen mit.",
            ["Auto buy best bars"] = "Beste Hantelstangen automatisch kaufen",
            ["Auto buy off"] = "Automatischer Kauf aus",
