        })
        local function Xd(f)
          local Si = f and tonumber(f)
          return Si and Si == Si and Si ~= math.huge and Si ~= -math.huge and not f:find("%s")
        end
        local function Qd(f, Td)
          return Td[f] and JZ.Text(f) or f
        end
        local function md(f, cC)
          if not cC then
            return
          end
          for UC, c in ipairs(jZ) do
            local ud = false
            for UC, vd in ipairs(c.scopes) do
              if cC == vd then
                ud = true
                break
              end
            end
            if ud then
              local nd = f:match(c.pattern)
              if nd and (not c.numeric or Xd(nd)) then
                return JZ.Text(c.template, {[c.placeholder] = nd})
              end
            end
          end
          if cC == "launchSweepMoon" then
            local CC = f:match("^Buying (.+)$")
            if CC then
              return JZ.Text("Buying {item}", {item = Qd(CC, Kd)})
            end
            local xd = f:match("^Need %$(%S+) available after the cash reserve%.$")
            if Xd(xd) and tonumber(xd) >= 0 then
              return JZ.Text("Need ${price} available after the cash reserve.", {price = xd})
            end
            local ld = f:match("^(.+) · native crew countdown%.$")
            if ld then
              return JZ.Text("{phase} · native crew countdown.", {phase = ld})
            end
          elseif cC == "launchBike" then
            local fd, Md = f:match("^Following highway lane (%d+); avoiding traffic (%a+)$")
            if fd and (Md == "left" or Md == "right") then
              local Wd = DZ == "en" and Md or JZ.Text(Md == "left" and "To the left" or "To the right")
              return JZ.Text("Following highway lane {lane}; avoiding traffic {direction}", {lane = fd, direction = Wd})
            end
            fd = f:match("^Following highway lane (%d+); traffic route clear$")
            if fd then
              return JZ.Text("Following highway lane {lane}; traffic route clear", {lane = fd})
            end
          elseif cC == "launchPowerLifters" then
            local xp, Gd, Sd, gd, rd = f:match("^Round (%d+) · (.+) · (%d+)/(%d+) reps%. (.*)$")
            if xp then
              return JZ.Text("Round {round} · {exercise} · {completed}/{target} reps. {detail}", {round = xp, exercise = Qd(Gd, Id), completed = Sd, target = gd, detail = JZ.Text(rd)})
            end
            local Nd, wd, Ld, Ud, qd, zd = f:match("^(.+) (%S+) / (%S+) · (%d+)/(%d+) muscles at target%. (.*)$")
            if Nd and Xd(wd) and Xd(Ld) then
              return JZ.Text("{muscle} {strength} / {target} · {completed}/{total} muscles at target. {detail}", {muscle = Qd(Nd, bd), strength = wd, target = Ld, completed = Ud, total = qd, detail = JZ.Text(zd)})
            end
          elseif cC == "launchClickEscape" then
            local od, Ed, jd = f:match("^(%d+) attempts / (%d+) confirmed presses / (%S+) confirmed clicks%.$")
            if od and Xd(jd) then
              return JZ.Text("{attempts} attempts / {presses} confirmed presses / {clicks} confirmed clicks.", {attempts = od, presses = Ed, clicks = jd})
            end
          elseif cC == "launchStealPetRide" then
            local Jd = f:match("^(.+) could not finish%. Its game state will be checked again%.$")
            if Jd and td[Jd] then
              return JZ.Text("{activity} could not finish. Its game state will be checked again.", {activity = JZ.Text(Jd)})
            end
          elseif cC == "launchAnimeEyes" then
            local cd = f:match("^Waiting for the current (%a+) action receipt%.$")
            if cd and Fd[cd] then
              return JZ.Text("Waiting for the current {action} action receipt.", {action = DZ == "en" and cd or JZ.Text(Fd[cd])})
            end
          elseif cC == "launchUrban" then
            local zd = f:match("^Waiting: (.+)%.$")
            if zd and ad[zd] then
              return JZ.Text("Waiting: {reason}.", {reason = JZ.Text(zd)})
            end
          end
        end
