              if oZ[ed][s] == nil then
                oZ[ed][s] = f
              end
            end
          end
        end
        function JZ.Text(f, PO, cC)
          if type(f) ~= "string" then
            return f
          end
          if cC == "NativeName" then
            return f
          end
          if cC == "RoomMetric" then
            if f == "Lobby" then
              return JZ.Text("Lobby")
            end
            local CA = f:match("^Room (%d+)$") or f == "Room ?" and "?"
            return CA and JZ.Text("Room {chapter}", {chapter = CA}) or f
          end
          if cC == "Navigation" and f == "Farming" then
            return DZ == "en" and f or JZ.Text("Farm")
          end
          if cC == "PowerGym" and f == "Nearest" then
            return JZ.Text("Nearest gym")
          end
          if cC == "PowerShop" then
            local ri, OA = f:match("^([^,]+), ([^,]+)$")
            if Pd[ri] and Pd[OA] then
              return JZ.Text("{first}, {second}", {first = JZ.Text(ri), second = JZ.Text(OA)})
            end
          elseif cC == "PowerGene" then
            local iA, pA = f:match("^(.+) %(([^()]+)%)$")
            local Wd = iA and (pA == "Gene" and JZ.Text("Gene") or EZ.GeneRarity[DZ][pA])
            if Wd then
              return JZ.Text("{gene} ({rarity})", {gene = iA, rarity = Wd})
            end
          end
          local ZA = oZ[DZ] and oZ[DZ][f]
          if ZA then
            return Zd(ZA, PO)
          end
          local dA = md(f, cC)
          if dA then
            return dA
          end
          local AA = f:match("^World (%d+) %(not released%)$")
          if AA then
            return JZ.Text("World {index} (not released)", {index = AA})
          end
          AA = f:match("^World (%d+)$")
          if AA then
            return JZ.Text("World {index}", {index = AA})
          end
          local kA, rd = f:match("^([^|]+) | ([^|]+)$")
          if Ad[kA] then
            if kd[rd] then
              return JZ.Text(kA) .. " | " .. JZ.Text(rd)
            end
            local BA, PA = rd:match("^(%S+) (.+)$")
            local Si = BA and tonumber(BA)
            if Si and Si == Si and Si ~= math.huge and Si ~= -math.huge then
              local Wd = Bd[PA] and JZ.Text("{amount} " .. PA, {amount = BA}) or rd
              return JZ.Text(kA) .. " | " .. Wd
            end
          end
          local HA, IA, bA = f:match("^This session: (.-) bikes, (.-) upgrades, (.-) event items purchased%.$")
          if HA and dd(HA) and dd(IA) and dd(bA) then
            return JZ.Text("This session: {bikes} bikes, {upgrades} upgrades, {items} event items purchased.", {bikes = HA, upgrades = IA, items = bA})
          end
          local Zp = f:match("^(%d+) selected$")
          if Zp then
            return JZ.Text("{count} selected", {count = Zp})
          end
          Zp = f:match("^(%d+) items selected$")
          if Zp then
            return JZ.Text("{count} items selected", {count = Zp})
          end
          Zp = f:match("^(%d+) cars selected$")
          if Zp then
            return JZ.Text("{count} cars selected", {count = Zp})
          end
          local KA = f:match("^(.+) %(locked%)$")
          if KA and not KA:find("{", 1, true) then
            return JZ.Text("{world} (locked)", {world = KA})
          end
          local FA, aA, tA = f:match("^(%a+) · Gym (.+) %(x([^%)]+)%)$")
          if (FA == "Strength" or FA == "Speed") and not aA:find("{", 1, true) and not tA:find("{", 1, true) then
            return JZ.Text(FA .. " · Gym {gym} (x{multiplier})", {gym = aA, multiplier = tA})
          end
          local XA = f:match("^Sell (.+) variants$") or f:match("^Include (.+) pets when they match your other sale rules%.$")
          if XA and ({Normal = true, Gold = true, Diamond = true, Rainbow = true, Inverted = true, Hacked = true})[XA] then
            local QA = f:sub(1, 4) == "Sell" and "Sell {variant} variants" or "Include {variant} pets when they match your other sale rules."
            return JZ.Text(QA, {variant = JZ.Text(XA)})
          end
          local UO = f:match("^Sell (.+) sizes$") or f:match("^Include (.+)%-size pets when they match your other sale rules%.$")
          if UO and ({Normal = true, Big = true, Huge = true, Titan = true})[UO] then
            local QA = f:sub(1, 4) == "Sell" and "Sell {size} sizes" or "Include {size}-size pets when they match your other sale rules."
            return JZ.Text(QA, {size = JZ.Text(UO)})
          end
          local TA, ld = f:match("^Trait: (.+)%. (.+)$")
          if TA and ({
            Idle = true, Unavailable = true, Ready = true, Waiting = true, Confirmed = true,
            ["Awaiting result"] = true, ["No valid choice"] = true,
          })[ld] then
            return JZ.Text("Trait: {trait}. {status}", {trait = TA, status = JZ.Text(ld)})
          end
          local mA, uA = f:match("^(%d+) requested; (%d+) confirmed%. Pending requests are not repeated%.$")
          if mA then
            return JZ.Text("{requested} requested; {confirmed} confirmed. Pending requests are not repeated.", {requested = mA, confirmed = uA})
          end
          local gd = f:match("^(.+) · Finding a ground route%.$")
          if gd and not gd:find("{", 1, true) then
            return JZ.Text("{target} · Finding a ground route.", {target = gd})
          end
          local vA, nA, xA, lA = f:match("^([%-]?%d[%d,%.]*) to ([%-]?%d[%d,%.]*) (%a+)%. Default: ([%-]?%d[%d,%.]*)%.$")
          if vA and (xA == "seconds" or xA == "studs") then
            return JZ.Text("{min}–{max} " .. xA .. ". Default: {default}.", {min = vA, max = nA, default = lA})
          end
          vA, nA, lA = f:match("^([%-]?%d[%d,%.]*) to ([%-]?%d[%d,%.]*)%. Default: ([%-]?%d[%d,%.]*)%.$")
          if vA then
            return JZ.Text("{min}–{max}. Default: {default}.", {min = vA, max = nA, default = lA})
          end
          local fA = f:match("^Key server returned HTTP (%d%d%d)%.$")
          if fA then
            return JZ.Text("The key server returned HTTP {status}. Try again.", {status = fA})
          end
          local Wp = f:match("^Appearance and saved preferences for (.+)%.$")
          if Wp and not Wp:find("{", 1, true) then
            return JZ.Text("Appearance and saved preferences for {game}.", {game = Wp})
          end
          local MA, WA = f:match("^Capture: ([%d%.]+) studs  /  ±([%d%.]+)°  ·  Adjust in Settings%.$")
          if MA then
            return JZ.Text("Capture: {distance} studs / ±{angle}° · Adjust in Settings.", {distance = MA, angle = WA})
          end
          local GA = oZ[DZ] and oZ[DZ][f]
          if not GA then
            local x, zd = f:match("^(.-) · (.+)$")
            if x and oZ[DZ] and oZ[DZ][zd] then
              return x .. " · " .. JZ.Text(zd, PO)
            end
          end
          if not GA then
            local SA, Di, gA = f:match("^(%s*)(.-)(%s*)$")
            if Di and oZ[DZ] and oZ[DZ][Di] then
              GA = SA .. oZ[DZ][Di] .. gA
            end
          end
          if not GA and f:find("\n", 1, true) then
            GA = f:gsub("[^\n]+", function(rA)
              return JZ.Text(rA, PO)
            end)
          end
          return Zd(GA or f, PO)
        end
        function JZ.Key(s, PO)
          return Zd(zZ[DZ] and zZ[DZ][s] or zZ.en[s] or s, PO)
        end
        local function NA(CC, Pp)
          local bC, f = pcall(function()
            return CC[Pp]
          end)
          if bC then
            return f
          end
        end
        local function wA(eC, CC)
          local HC = CC.ClassName
          local Pp = (HC == "TextLabel" or HC == "TextButton") and "Text" or HC == "TextBox" and "PlaceholderText"
          if not Pp or CC:GetAttribute("SchoolHubNoTranslate") == true or CC.Name == "MetricValue" and CC:GetAttribute("SchoolHubLocaleScope") ~= "RoomMetric" then
            return
          end
          if not eC.nodes[CC] then
            eC.nodes[CC] = {property = Pp, scope = eC.scope}
          end
        end
        local function LA(CC, c)
          if CC:GetAttribute("SchoolHubNoTranslate") == true or CC.Name == "MetricValue" and CC:GetAttribute("SchoolHubLocaleScope") ~= "RoomMetric" then
            return
          end
          if not NA(CC, "Parent") then
            return
          end
          local rC = NA(CC, c.property)
          if type(rC) ~= "string" then
            return
          end
          if rC ~= c.output then
            c.source = rC
          end
          local UA = JZ.Text(c.source or rC, nil, CC:GetAttribute("SchoolHubLocaleScope") or c.scope)
          c.output = UA
          if UA ~= rC then
            pcall(function()
              CC[c.property] = UA
            end)
          end
        end
        function JZ.Refresh(sC)
          local eC = BC[sC]
          if not eC then
            return
          end
          for CC, c in pairs(eC.nodes) do
            LA(CC, c)
          end
        end
        function JZ.Source(CC, Pp)
          for UC, eC in pairs(BC) do
            local c = eC.nodes[CC]
            if c and c.property == (Pp or "Text") then
              local rC = NA(CC, c.property)
              return rC == c.output and c.source or rC
            end
          end
          return NA(CC, Pp or "Text")
        end
        function JZ.Attach(sC, qA, cC)
          if BC[sC] then
            return
          end
          local eC = {nodes = setmetatable({}, {__mode = "k"}), connections = {}, refresh = qA, scope = cC}
          BC[sC] = eC
          for UC, CC in ipairs(sC:GetDescendants()) do
            wA(eC, CC)
          end
          if sC.DescendantAdded then
            eC.connections[#eC.connections + 1] = sC.DescendantAdded:Connect(function(CC)
              wA(eC, CC)
              local c = eC.nodes[CC]
              if c then
                LA(CC, c)
              end
            end)
          end
          eC.connections[#eC.connections + 1] = sC.Destroying:Connect(function()
            for UC, QC in ipairs(eC.connections) do
              pcall(QC.Disconnect, QC)
            end
            BC[sC] = nil
          end)
          JZ.Refresh(sC)
        end
