          local oA = qZ.Text
          qZ.Text = function(f, PO, cC)
            if cC == "launchFruit" and type(f) == "string" then
              local KA, jA = f:match("^World (%d+) · Stage (%d+)$")
              if KA then
                return qZ.Text("World {world} · Stage {stage}", {world = KA, stage = jA}, cC)
              end
              local JA = f:match("^Training (%d+)$")
              if JA then
                return qZ.Text("Training {zone}", {zone = JA}, cC)
              end
              jA = f:match("^Stage (%d+)$")
              if jA then
                return qZ.Text("Stage {stage}", {stage = jA}, cC)
              end
            end
            local EA = (cC == "launchFruit" or cC == "Navigation" and f == "Greenhouse") and zA[f]
            if EA then
              local wC = EA[qZ.Code()] or EA.en
              return wC:gsub("{([%w_]+)}", function(s)
                return PO and PO[s] and tostring(PO[s]) or "{" .. s .. "}"
              end)
            end
            return oA(f, PO, cC)
          end
        end
