          local eA = JZ.Text
          local RA = {
            Rebirth = "Auto rebirth", Hatch = "Auto eggs", EquipBest = "Auto equip best pets",
            Skill = "Auto skill tree", Upgrade = "Auto gem upgrades", Physical = "Auto physical upgrades",
            DoubleJump = "Auto physical upgrades", Craft = "Auto golden", Enchant = "Auto enchant",
            Delete = "Auto delete spare pets", DigBegin = "Auto dig", DigHit = "Auto dig",
            FishCast = "Auto fish", FishReel = "Auto fish", FishCollect = "Auto fish",
            DefenseStart = "Auto pet defense", DefenseAttack = "Auto pet defense",
            DefenseDrop = "Auto pet defense", DefenseClaim = "Auto pet defense",
            DefenseReturn = "Auto pet defense", Candy = "Auto candy shop", Spin = "Auto spin wheel",
            IndexReward = "Auto claim rewards", ClaimPotion = "Auto claim rewards",
            Offline = "Auto claim rewards", Quest = "Auto claim quests", Brew = "Auto brew potions",
            BuyPotion = "Auto buy potions", UsePotion = "Auto use potions", UnlockZone = "Auto unlock zones",
            UnlockIsland = "Auto unlock islands",
          }
          JZ.Text = function(f, PO, cC)
            if cC == "launchTapSimulatorReborn" and type(f) == "string" then
              local DZ = JZ.Code()
              local yA = YA[DZ]
              if yA and yA[f] then
                return yA[f]
              end
              if DZ == "ru" then
                local hA, CC, xd = f:match("^Unlock (.-) for (.-) %((.-)%)$")
                if hA then
                  return "Откройте " .. hA .. " для " .. CC .. " (" .. xd .. ")"
                end
                local BA, PA, CC, VA = f:match("^Need (%S+) (%S+) for (.-) %(available (.-)%)$")
                if BA then
                  return "Нужно " .. BA .. " " .. PA .. " для " .. CC .. " (есть " .. VA .. ")"
                end
                local Zp, sA = f:match("^Need (%d+) unprotected duplicate pets for (%d+)%% chance$")
                if Zp then
                  return "Нужно " .. Zp .. " свободных дубликатов для шанса " .. sA .. "%"
                end
                local Ck = f:match("^Upgrade machine is not loaded: (.+)$")
                if Ck then
                  return "Станок ещё не загружен: " .. Ck
                end
                for UC, Ok in ipairs({"Confirmed: ", "Confirming: "}) do
                  if f:sub(1, #Ok) == Ok then
                    local cd = f:sub(#Ok + 1)
                    return yA[Ok == "Confirmed: " and "Confirmed" or "Confirming"] .. ": " .. JZ.Text(RA[cd] or cd, nil, cC)
                  end
                end
                local WO = f:match("^Pet defense cooldown: (%d+)s$")
                if WO then
                  return "Защита питомцами будет доступна через " .. WO .. " с"
                end
                for UC, Ok in ipairs({
                  "Original module is not ready: ", "Unable to read original module: ",
                  "Original method unavailable: ",
                }) do
                  if f:sub(1, #Ok) == Ok then
                    return (Ok == "Original module is not ready: " and "Модуль ещё не готов: " or Ok == "Unable to read original module: " and "Не удалось прочитать модуль: " or "Метод модуля недоступен: ") .. f:sub(#Ok + 1)
                  end
                end
              end
            end
            return eA(f, PO, cC)
          end
        end
