          local oA = JZ.Text
          JZ.Text = function(f, PO, cC)
            if cC == "launchAntEvolution" and type(f) == "string" then
              local EA = sd[f]
              if EA then
                return (EA[JZ.Code()] or EA.en):gsub("{([%w_]+)}", function(s)
                  return PO and PO[s] ~= nil and tostring(PO[s]) or "{" .. s .. "}"
                end)
              end
              local ik, pk, Zk, dk, Ak = f:match("^HP (%d+) / (%d+) | Power (%d+) / (%d+) | DNA (%d+)$")
              if ik then
                return JZ.Text("HP {hp} / {max} | Power {power} / {need} | DNA {dna}", {hp = ik, max = pk, power = Zk, need = dk, dna = Ak}, cC)
              end
              ik, pk = f:match("^HP (%d+) / (%d+); returning at full health$")
              if ik then
                return JZ.Text("HP {hp} / {max}; returning at full health", {hp = ik, max = pk}, cC)
              end
              local MA = f:match("^(%d+) studs$")
              if MA then
                return JZ.Text("{distance} studs", {distance = MA}, cC)
              end
              local iO = f:match("^Lost egg (%d+)$")
              if iO then
                return JZ.Text("Lost egg {index}", {index = iO}, cC)
              end
            end
            return oA(f, PO, cC)
          end
        end
