          local oA = JZ.Text
          JZ.Text = function(f, PO, cC)
            if cC == "launchVoxelWars" then
              if type(f) == "string" then
                local EA = sd[f]
                if EA then
                  return (EA[JZ.Code()] or EA.en):gsub("{([%w_]+)}", function(s)
                    return PO and PO[s] ~= nil and tostring(PO[s]) or "{" .. s .. "}"
                  end)
                end
                local mA, uA = f:match("^(%d+) requested; (%d+) confirmed%. Pending requests are not repeated%.$")
                if mA then
                  return JZ.Text("{requested} requested; {confirmed} confirmed. Pending requests are not repeated.", {requested = mA, confirmed = uA}, cC)
                end
              end
              return oA(f, PO, "launchHypershot")
            end
            return oA(f, PO, cC)
          end
        end
