        end
        do
          local TZ, vZ = iB.Internal, iB.Locale
          function TZ.rowGlow(YC, EA, qO, oO, YP)
            if not EA.glow then
              EA.glow = TZ.rect(EA.item, "StudioEnabledGlow", 2, 4, qO - 4, oO - 8, YC.colors.surface, 0)
              TZ.round(EA.glow, 8)
              EA.glow.BackgroundTransparency = 1
            end
            TZ.geometry(EA.glow, 2, 4, qO - 4, math.max(1, oO - 8))
            TZ.surfaceGradient(EA.glow, YC.colors.surface, YC.colors.accent, iB.Prefs().base == "pearl" and .18 or .09, .95, 10)
            if EA.enabledGlow ~= YP then
              EA.enabledGlow = YP
              TZ.tween(YC, EA.glow, {BackgroundTransparency = YP and 0 or 1}, .21, nil, TZ.curves.ease)
            end
          end
          local function ZF(Ip)
            local iP, pP = 0, 1
            for UC = 1, 18 do
              local kZ = (iP + pP) * .5
              local BZ = 1 - kZ
              local ZP = 3 * BZ * kZ * kZ * .58 + kZ * kZ * kZ
              if not (ZP < Ip) then
                pP = kZ
              else
                iP = kZ
              end
            end
            local kZ = (iP + pP) * .5
            return 3 * (1 - kZ) * kZ * kZ + kZ * kZ * kZ
          end
          function iB.PulseAt(WO)
            local ld = WO % 2.8 / 2.8
            if ld <= .45 then
              local kZ = ZF(ld / .45)
              return .85 + .15 * kZ, 5 * kZ, .09 * (1 - kZ)
            end
            local kZ = ZF((ld - .45) / .55)
            return 1 - .15 * kZ, 5 * (1 - kZ), 0
          end
          function iB:PulseDots(WO)
            self.pulseHalos = self.pulseHalos or {}
            self.pulseStates = self.pulseStates or {}
            local dF = iB.MotionEnabled() and self.state.paused ~= true
            for UC, AF in ipairs({self.dot, self.statusDot}) do
              local BI = true
              local kF = AF
              while kF do
                local bC, f = pcall(function()
                  return kF.Visible
                end)
                if bC and f == false then
                  BI = false
                  break
                end
                if kF.ClassName == "ScreenGui" and kF.Enabled == false then
                  BI = false
                  break
                end
                kF = kF.Parent
              end
              local vB = dF and BI
              local Ai = self.pulseStates[AF] or {}
              self.pulseStates[AF] = Ai
              if not vB or not Ai.active then
                Ai.started = WO
              end
              Ai.active = vB
              local oP, BF, PF = iB.PulseAt(WO - (Ai.started or WO))
              local HF = self.pulseHalos[AF]
              if not HF then
                HF = TZ.rect(AF.Parent, "StudioPulseHalo", 0, 0, 5, 5, self.colors.accent, (AF.ZIndex or 1) - 1)
                HF.AnchorPoint = Vector2.new(.5, .5)
                TZ.round(HF, 20)
                self.pulseHalos[AF] = HF
              end
              if HF.Parent ~= AF.Parent then
                HF.Parent = AF.Parent
              end
              local IF = AF.Position
              HF.Position = UDim2.new(IF.X.Scale, IF.X.Offset + 2.5, IF.Y.Scale, IF.Y.Offset + 2.5)
              HF.Size = UDim2.fromOffset(5 + BF * 2, 5 + BF * 2)
              HF.BackgroundColor3 = self.colors.accent
              HF.BackgroundTransparency = 1 - PF
              HF.Visible = vB
              AF.BackgroundTransparency = self.state.paused and .55 or vB and 1 - oP or 0
            end
          end
          function iB:Footer(qO, oO, Hb, ub)
            local Wi, Qp = self.context, self.colors
            local bF = Wi.footer
            if not bF then
              return oO - 1
            end
            local lK = iB.Prefs().density == "compact"
            local Ip = self.mobile and 1 or 77
            local HZ = qO - Ip - 1
            local Rp = self.shortMobile and 33 or lK and 37.5 or self.mobile and 45.5 or 43.5
            local bp = oO - Rp - 1
            bF.Visible = not Hb
            TZ.geometry(bF, Ip, bp - ub, HZ, Rp)
            bF.BackgroundTransparency = 1
            for UC, eH in ipairs(bF:GetChildren()) do
              if eH.ClassName == "UIStroke" then
                eH.Enabled = false
              end
            end
            self.footerRule = self.footerRule or TZ.rect(bF, "StudioFooterRule", 0, 0, HZ, 1, Qp.border, 1)
            TZ.geometry(self.footerRule, 0, 0, HZ, 1)
            self.footerRule.BackgroundColor3 = Qp.border
            local fA = Wi.footerStatus or TZ.find(bF, "FooterStatus")
            local rd = Wi.footerDetail or TZ.find(bF, "FooterDetail")
            local KF = Wi.pauseButton or TZ.find(bF, "GlobalPause")
            if rd then
              rd.Visible = false
            end
            if KF then
              KF.Visible = false
            end
            local wI = lK and 18 or self.mobile and 15 or 25
            self.footerLegend = self.footerLegend or TZ.label(bF, "StudioMenuLegend", "", 0, 0, 120, Rp, Qp.muted, 11, false, 2)
            self.footerLegend:SetAttribute("SchoolHubNoTranslate", true)
            self.footerLegend.TextWrapped = false
            self.footerLegend.Text = vZ.Text(self.mobile and "Touch controls" or "Toggle menu")
            self.footerLegend.TextColor3 = Qp.muted
            self.footerLegend.Visible = not self.shortMobile
            local FF = TZ.textWidth(Wi, self.footerLegend.Text, 11, self.footerLegend.Font)
            TZ.geometry(self.footerLegend, HZ - wI - FF, 0, FF, Rp)
            if not self.footerKeycap then
              self.footerKeycap = TZ.rect(bF, "StudioMenuKeycap", 0, 0, 39, 15, Qp.panel, 2)
              TZ.round(self.footerKeycap, 3)
              TZ.stroke(self.footerKeycap, Qp.border)
              local wC = TZ.label(self.footerKeycap, "KeycapText", "Insert", 0, 0, 39, 15, Qp.muted, 10, false, 3)
              wC.Font = Enum.Font.Code
              wC.TextXAlignment = Enum.TextXAlignment.Center
            end
            self.footerKeycap.Visible = not self.mobile
            self.footerKeycap.BackgroundTransparency = 1
            TZ.geometry(self.footerKeycap, HZ - wI - FF - 47, (Rp - 15) / 2, 39, 15)
            local aF = self.shortMobile and 0 or FF + (self.mobile and 12 or 59)
            if fA then
              fA.Visible = true
              fA.TextSize = 11
              fA.Font = Enum.Font.Gotham
              fA.TextWrapped = false
